from pathlib import Path
import hashlib,json,sys
root=Path(sys.argv[1]); selected=sys.argv[2]
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
p=root/'manifest.json';m=json.loads(p.read_text());m['selected_portrait']=f'candidates/{selected}_74x100_candidate.png';m['selected_preview']=f'previews/{selected}_1x_8x.png';m['selected_portrait_sha256']=sha(root/m['selected_portrait']);m['scope']='Portrait redraw only; old art, character cards, code, runtime and repository history unchanged.';m['source_provenance']='sources/source_manifest.json';m['full_tool_parameters']=[f'prompts/{x.stem}.json' for x in sorted((root/'tool_returns').glob('portrait_v*.json'))];m['full_tool_returns']=[str(x.relative_to(root)) for x in sorted((root/'tool_returns').glob('portrait_v*.json'))];m['generated_image_count']=len(m['full_tool_returns']);m['sha256_inventory_excludes_self']=True;m['files']=[{'path':str(x.relative_to(root)),'bytes':x.stat().st_size,'sha256':sha(x)} for x in sorted(root.rglob('*')) if x.is_file() and x.name not in ('manifest.json','SHA256SUMS.txt')];p.write_text(json.dumps(m,ensure_ascii=False,indent=2));(root/'SHA256SUMS.txt').write_text('\n'.join(f'{sha(x)}  {x.relative_to(root)}' for x in sorted(root.rglob('*')) if x.is_file() and x.name!='SHA256SUMS.txt')+'\n');print(m['selected_portrait_sha256'])
